package com.hkdn.backend.service;
import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import java.util.Optional;
@Component public class UnavailableBlockchainGateway implements BlockchainGateway {private final boolean enabled;private final String rpc;private final String contract;public UnavailableBlockchainGateway(@Value("${blockchain.enabled:false}") boolean enabled,@Value("${blockchain.rpc-url:}") String rpc,@Value("${blockchain.contract-address:}") String contract){this.enabled=enabled;this.rpc=rpc;this.contract=contract;}public Optional<String> recordHash(String h){return Optional.empty();}public Optional<Boolean> hasHash(String h){return Optional.empty();}public Optional<String> revoke(String h){return Optional.empty();}public boolean available(){return enabled&&!rpc.isBlank()&&!contract.isBlank();}}
